-- Safety check: stops with a plain message if part 5 has not been run.
do $$ begin
  if to_regclass('public.submissions') is null then
    raise exception 'The parts must be run in order. Start with part 1 (1-schema.sql): the tables do not exist yet.';
  end if;
end $$;
do $$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'members' and column_name = 'title') then
    raise exception 'Run part 5 (5-titles.sql) first.';
  end if;
end $$;

-- Seed: one contest in "setup" with the four starting categories.
-- Idempotent. Included as supabase/setup/6-starting-data.sql; used directly by the local test suite.
-- Set the real dates afterwards on /admin/contest.

insert into contests (organization_id, name, start_at, end_at)
select o.id, 'Contest 1', now() + interval '7 days', now() + interval '37 days'
from organizations o
where o.slug = 'default'
  and not exists (select 1 from contests c where c.organization_id = o.id);

insert into categories (contest_id, name, points, reference_label, reference_hint, sort_order)
select c.id, v.name, v.points, v.label, v.hint, v.sort_order
from (
  select c.id
  from contests c
  join organizations o on o.id = c.organization_id
  where o.slug = 'default'
  order by c.created_at desc
  limit 1
) c
cross join (values
  ('New Account',              2, 'Account username',     'jane_designs',                  1),
  ('New Gig',                  1, 'Gig title',            'i will build hubspot workflows', 2),
  ('New Message',              2, 'Buyer username + date', 'buyer123 2026-10-20',          3),
  ('Converted Message / Order', 5, 'Fiverr order number', 'FO1234567890',                   4)
) as v(name, points, label, hint, sort_order)
where not exists (
  select 1 from categories existing
  where existing.contest_id = c.id and existing.name = v.name
);


